scwin.grid1_ongroupby = function(options) {
    options.rowNumHeader = {
        inputType: 'expression',
        expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
        align: 'left',
        colSpan: 5
    };
    options.rowNumFooter = {
        colSpan: 3
    };
    options.rowStatusFooter = {
        value: '합계'
    };
    options.groupbyFooter = [{
        inputType: 'expression',
        expression: 'SUM("col3")'
    }];
    grid1.groupby(options);
    return false;
    //				return true;
}
scwin.grid2_ongroupby = function(options) {
    options.rowNumHeader = {
        inputType: 'expression',
        expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
        align: 'left',
        colSpan: 5
    };
    options.rowNumFooter = {
        colSpan: 3
    };
    options.rowStatusFooter = {
        value: '합계'
    };
    options.groupbyFooter = [{
        inputType: 'expression',
        expression: 'SUM("col3")'
    }];
    this.groupby(options);
}
scwin.selectbox1_onviewchange = function(info) {
    var data = eval("scwin.data" + info.newValue);
    dataList1.setData(data.slice(0));
}
scwin.trigger1_onclick = function() {
    var data = eval("scwin.data" + selectbox1.getValue());
    dataList1.setData(data.slice(0));
}
scwin.grid1_groupbyFilterBoxFormatter = function(f) {
    console.log(JSON.stringify(f));
}
scwin.trigger2_onclick = function(e) {
    var data = eval("scwin.data" + selectbox1.getValue());
    dataList1.setData(data.slice(0));
    var options = {
        sortIndex: [0],
        sortOrder: [0]
    }
    scwin.grid1_ongroupby(options);
};
scwin.checktype = function() {
    return typeof WebSquare.wUnit.getJq('.w2grid_groupbyZone_column_value')[0] === 'undefined';
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일 실행 후 '조회2'버튼을 클릭한다.
    //1. Run the sample file and click the 'Query 2' button.
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 1. 분류1 항목이 groupby되어진다.
    //1. Category 1 items are groupby.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column_value').text() == '분류1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. groupby되어진 분류1을 필터링한 후 '조회2'버튼을 클릭한다.
    //2. Filter the group 1 group 1 and click the 'View 2' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column_labelDiv')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid1_groupbyZone_list_items_main').childNodes[2].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid1_groupbyZone_list_items_main').childNodes[3].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid1_groupbyZone_list_items_main').childNodes[4].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 2. groupby filter기능이 정상동작한다.(이전에는 상단의 groupby항목이 사라지고 기능이 동작하지 않았음)
    //2. The groupby filter function works normally (Previously, the groupby item at the top disappears and the function did not work)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column_value').text() == '분류1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. groupby되어진 분류1항목을 삭제한다.
    //3. Delete the group 1 item that is groupby.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column_closeButtonImg')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 3. 정상적으로 삭제되어진다.
    //3. Normally deleted.
    WebSquare.wUnit.addCommand("assert", "scwin.checktype()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
